next.layout:
import 'fire-design/css';
import './fire-theme.css';
import { headers } from 'next/headers';
import { FireRuntime } from './fire-runtime';
import { FireSprite } from './fire-sprite';
import { jsonForScript } from './fire-export';
import labels from './labels.json';
import { theme } from './theme';

export default async function RootLayout({ children }: { children: React.ReactNode }) {
  const nonce = (await headers()).get('x-nonce') ?? undefined;
  return (
    <html lang="en" {...theme} suppressHydrationWarning>
      <head>
        <script src="/fire/boot.js" nonce={nonce} />
        <script type="application/json" data-fd-labels="" dangerouslySetInnerHTML={{ __html: jsonForScript(labels) }} />
      </head>
      <body>
        <FireSprite />
        {children}
        <FireRuntime />
      </body>
    </html>
  );
}

next.runtime:
'use client';
import { useEffect } from 'react';
import { usePathname } from 'next/navigation';
export function FireRuntime() {
  const pathname = usePathname();
  useEffect(() => {
    let live = true;
    import('fire-design').then((fire) => { if (live) fire.init(document); });
    return () => { live = false; };
  }, [pathname]);
  return null;
}

next.proxy:
import { NextResponse, type NextRequest } from 'next/server';
export function proxy(request: NextRequest) {
  const nonce = Buffer.from(crypto.randomUUID()).toString('base64');
  const dev = process.env.NODE_ENV === 'development';
  const csp = ["default-src 'self'", `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'${dev ? " 'unsafe-eval'" : ''}`, `style-src 'self'${dev ? " 'unsafe-inline'" : ''}`, "img-src 'self' data:", "font-src 'self'", "object-src 'none'", "base-uri 'self'", "frame-ancestors 'none'"].join('; ');
  const headers = new Headers(request.headers);
  headers.set('x-nonce', nonce);
  headers.set('Content-Security-Policy', csp);
  const response = NextResponse.next({ request: { headers } });
  response.headers.set('Content-Security-Policy', csp);
  return response;
}
export const config = { matcher: [{ source: '/((?!_next/static|_next/image|favicon.ico|fire/).*)' }] };
